import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: handl_bench","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_bench/handl_bench.md","filePath":"api/host/handl_bench/handl_bench.md"}`),a={name:`api/host/handl_bench/handl_bench.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_bench</strong></p><h1 id="module-handl-bench" tabindex="-1">Module: handl_bench <a class="header-anchor" href="#module-handl-bench" aria-label="Permalink to “Module: handl_bench”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Constants</strong></p><ul><li><a href="#eval-sample"><code>EVAL_SAMPLE</code></a> - A self-contained, <strong>evaluable</strong> module for the pipeline bench.</li><li><a href="#inference-sample"><code>INFERENCE_SAMPLE</code></a> - An inference-heavy module for the <code>infer</code> bench.</li><li><a href="#sample"><code>SAMPLE</code></a> - A representative canonical statement: member access, a call, and literal</li></ul><hr><h2 id="handl-bench-eval-sample" tabindex="-1">handl_bench::EVAL_SAMPLE <a class="header-anchor" href="#handl-bench-eval-sample" aria-label="Permalink to “handl_bench::EVAL_SAMPLE”">​</a></h2><p><em>Constant</em>: <code>&amp;str</code></p><p>A self-contained, <strong>evaluable</strong> module for the pipeline bench.</p><p>[<code>SAMPLE</code>] deliberately leaves its callee unbound so it exercises parsing without needing a runtime; evaluating it fails with <code>function &#39;qux…&#39; not found</code>. Evaluation needs every name bound, so this binds the function first.</p><p>Note: this previously used the <code>|&gt;</code> pipe operator (<code>&quot;f = x ~&gt; x; 1 |&gt; f&quot;</code>), inherited from <code>kit-canonical/benches/perf.rs</code>. <code>|&gt;</code> was <strong>removed</strong> from the canonical grammar (<code>handl-kit-data-prelude/data/ast.yaml</code>, &quot;Removed: … pipe …&quot;), so the sample no longer parsed and <code>pipeline/parse_and_eval</code> panicked on its first iteration. Plain application is the supported form.</p><h2 id="handl-bench-inference-sample" tabindex="-1">handl_bench::INFERENCE_SAMPLE <a class="header-anchor" href="#handl-bench-inference-sample" aria-label="Permalink to “handl_bench::INFERENCE_SAMPLE”">​</a></h2><p><em>Constant</em>: <code>&amp;str</code></p><p>An inference-heavy module for the <code>infer</code> bench.</p><p>Three chained arrows plus an application, so the <code>.hnl</code> model has to synthesize a type for each binding <em>and</em> for the application site — the shape <code>handl-typecheck-infer</code> used to be measured on. Validated against <code>hnl typecheck</code> (<code>&lt;path&gt;: ok</code>).</p><h2 id="handl-bench-sample" tabindex="-1">handl_bench::SAMPLE <a class="header-anchor" href="#handl-bench-sample" aria-label="Permalink to “handl_bench::SAMPLE”">​</a></h2><p><em>Constant</em>: <code>&amp;str</code></p><p>A representative canonical statement: member access, a call, and literal arguments (number, negative float, string, array, record).</p><p>Deliberately a <em>single</em> statement — the Pratt parser parses one statement per call, so a multi-statement module would need the module splitter and would measure that rather than the grammar.</p><p>The pre-refactor sample (<code>handle foo as bar(...)</code>) was retired-dialect syntax and no longer parses.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};